+    :root {
+      color-scheme: dark;
+      --bg: #0b1020;
+      --panel: rgba(17, 24, 39, 0.9);
+      --panel-border: rgba(148, 163, 184, 0.18);
+      --text: #e5eefc;
+      --muted: #9fb0cc;
+      --accent: #7dd3fc;
+      --accent-strong: #38bdf8;
+      --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
+    }
+
+    * {
+      box-sizing: border-box;
+    }
+
+    body {
+      margin: 0;
+      min-height: 100vh;
+      font-family: Arial, Helvetica, sans-serif;
+      background:
+        radial-gradient(circle at top, rgba(56, 189, 248, 0.14), transparent 32%),
+        linear-gradient(180deg, #0f172a 0%, var(--bg) 100%);
+      color: var(--text);
+      display: grid;
+      place-items: center;
+      padding: 32px 16px;
+    }
+
+    .faq {
+      width: min(760px, 100%);
+      background: var(--panel);
+      border: 1px solid var(--panel-border);
+      border-radius: 24px;
+      padding: 32px;
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(18px);
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(2rem, 4vw, 2.8rem);
+      letter-spacing: -0.04em;
+    }
+
+    .intro {
+      margin: 0 0 28px;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    .example + .example {
+      margin-top: 14px;
+    }
+
+    .example {
+      border: 1px solid rgba(125, 211, 252, 0.15);
+      border-radius: 18px;
+      background: rgba(15, 23, 42, 0.82);
+      overflow: hidden;
+      transition: border-color 0.2s ease, transform 0.2s ease;
+    }
+
+    .example:hover {
+      border-color: rgba(125, 211, 252, 0.3);
+      transform: translateY(-1px);
+    }
+
+    .question {
+      width: 100%;
+      border: 0;
+      background: transparent;
+      color: inherit;
+      font: inherit;
+      padding: 20px 22px;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      cursor: pointer;
+      text-align: left;
+      font-size: 1.05rem;
+      font-weight: 700;
+    }
+
+    .question:focus-visible {
+      outline: 2px solid var(--accent);
+      outline-offset: -2px;
+    }
+
+    .indicator {
+      flex: 0 0 auto;
+      width: 28px;
+      height: 28px;
+      border-radius: 999px;
+      display: grid;
+      place-items: center;
+      color: var(--accent);
+      background: rgba(56, 189, 248, 0.1);
+      transition: transform 0.2s ease, background-color 0.2s ease;
+    }
+
+    .example.is-open .indicator {
+      transform: rotate(45deg);
+      background: rgba(56, 189, 248, 0.18);
+    }
+
+    .details {
+      display: grid;
+      grid-template-rows: 0fr;
+      transition: grid-template-rows 0.28s ease;
+    }
+
+    .example.is-open .details {
+      grid-template-rows: 1fr;
+    }
+
+    .details-inner {
+      overflow: hidden;
+    }
+
+    .answer {
+      margin: 0;
+      padding: 0 22px 22px;
+      color: var(--muted);
+      line-height: 1.65;
+    }
+
+    .answer strong {
+      color: var(--text);
+    }
+
+    @media (max-width: 600px) {
+      .faq {
+        padding: 24px 18px;
+        border-radius: 20px;
+      }
+
+      .question,
+      .answer {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="faq">
+    <h1>Cat FAQ</h1>
+    <p class="intro">A polished guide to common cat questions. Each answer starts hidden, so you can expand only what you want to read.</p>
+
+    <div class="example">
+      <button class="question" type="button" aria-expanded="false">
+        <span>Why do cats purr?</span>
+        <span class="indicator" aria-hidden="true">+</span>
+      </button>
+      <div class="details" hidden>
+        <div class="details-inner">
+          <p class="answer"><strong>Cats often purr when they feel content,</strong> but they may also purr when they are nervous, seeking comfort, or recovering from stress. It is a versatile sound linked to communication and self-soothing.</p>
+        </div>
+      </div>
+    </div>
+
+    <div class="example">
+      <button class="question" type="button" aria-expanded="false">
+        <span>Why do cats sleep so much?</span>
+        <span class="indicator" aria-hidden="true">+</span>
+      </button>
+      <div class="details" hidden>
+        <div class="details-inner">
+          <p class="answer"><strong>Cats are natural predators built for short bursts of energy,</strong> so they conserve power by resting a lot. Many healthy adult cats sleep between 12 and 16 hours a day.</p>
+        </div>
+      </div>
+    </div>
+
+    <div class="example">
+      <button class="question" type="button" aria-expanded="false">
+        <span>How can I help my cat stay entertained indoors?</span>
+        <span class="indicator" aria-hidden="true">+</span>
+      </button>
+      <div class="details" hidden>
+        <div class="details-inner">
+          <p class="answer"><strong>Offer a mix of climbing, scratching, and hunting-style play.</strong> Cat trees, puzzle feeders, wand toys, and window perches help indoor cats stay active, curious, and mentally engaged.</p>
+        </div>
+      </div>
+    </div>
+
+    <div class="example">
+      <button class="question" type="button" aria-expanded="false">
+        <span>Why do cats knead with their paws?</span>
+        <span class="indicator" aria-hidden="true">+</span>
+      </button>
+      <div class="details" hidden>
+        <div class="details-inner">
+          <p class="answer"><strong>Kneading is usually a comforting behavior</strong> that starts in kittenhood during nursing. Adult cats may knead soft blankets, beds, or laps when they feel relaxed and secure.</p>
+        </div>
+      </div>
+    </div>
+
+    <div class="example">
+      <button class="question" type="button" aria-expanded="false">
+        <span>What does a slowly blinking cat mean?</span>
+        <span class="indicator" aria-hidden="true">+</span>
+      </button>
+      <div class="details" hidden>
+        <div class="details-inner">
+          <p class="answer"><strong>A slow blink is often a sign of trust and calm.</strong> Many people call it a cat smile. If you slowly blink back, your cat may respond in the same relaxed way.</p>
+        </div>
+      </div>
+    </div>
+  </main>
+
+  <script>
+    const examples = document.querySelectorAll(".example");
+
+    examples.forEach((example) => {
+      const button = example.querySelector(".question");
+      const details = example.querySelector(".details");
+
+      button.addEventListener("click", () => {
+        const isOpen = button.getAttribute("aria-expanded") === "true";
+
+        button.setAttribute("aria-expanded", String(!isOpen));
+        example.classList.toggle("is-open", !isOpen);
+        details.hidden = isOpen;
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
